int a = 10, b = 5, c = 2;

// Relying on default precedence (* before +)
int result_default = a + b * c; // 20

// Explicit grouping for clarity (even if default works)
int result_clear = a + (b * c); // 20

// Explicit grouping to enforce different order
// Avoids bugs caused by misinterpreting precedence
int result_forced = (a + b) * c; // (15 * 2) -> 30

bool x = true, y = false, z = true;

// Relies on && having higher precedence than ||
bool check1 = x || y && z; // (x || (y && z))

// Explicit grouping for maintenance and clarity
bool check2 = (x || y) && z;
bool check3 = x || (y && z);

// check1 == check3
// check2 != check3
// Grouping dictates intent
